/* gateway.h - domestic vocabulary only; no <curl/curl.h> here */
typedef struct booking_gw booking_gw;
booking_gw *booking_gw_open(const char *base_url);
int booking_gw_slots(booking_gw *gw, long minutes, slot_out *out, size_t cap);
void booking_gw_close(booking_gw *gw);

/* gateway.c - the only translation unit that knows libcurl */
int booking_gw_slots(booking_gw *gw, long minutes, slot_out *out, size_t cap)
{
    if (curl_easy_setopt(gw->curl, CURLOPT_URL, build_url(gw->base, minutes))) return GW_ERR_CONFIG;
    CURLcode rc = curl_easy_perform(gw->curl);            /* foreign call, hidden */
    return rc == CURLE_OK ? parse_slots(gw->buf, out, cap) : gw_err_from_curl(rc);
}
